\begin{tikzpicture}[x=1.35cm,y=1.05cm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\draw[line width=0.4pt] (-1.8,4.1)--(2.6,4.1) (-0.7,3.65)--(-0.7,4.55);
\node[anchor=east] at (-0.8,4.35) {Sign of $y$};
\node[anchor=east] at (-0.8,3.85) {$x$ values};
\node at (0,4.35) {$+$};\node at (1,4.35) {$0$};\node at (2,4.35) {$+$};
\fill (1,4.1) circle (1.5pt);\node at (1,3.85) {$1$};
\draw[->,line width=0.5pt] (-0.7,0)--(2.65,0) node[right] {$x$};
\draw[->,line width=0.5pt] (0,-0.45)--(0,3.2) node[above] {$y$};
\draw[line width=0.8pt,domain=-0.65:2.65,samples=101] plot (\x,{(\x-1)^2});
\fill (1,0) circle (1.5pt) (0,1) circle (1.5pt);
\node[below left] at (0,0) {$O$};\node[below] at (1,0) {$1$};\node[left] at (0,1) {$1$};
\node[anchor=west] at (0.45,3) {$y=(x-1)^2$};
\end{tikzpicture}

